<script setup lang="ts">import{onMounted,ref}from'vue';import{Workflow,ArrowUpRight,FolderKanban}from'lucide-vue-next';import{api}from'../api';import EmptyState from'../components/EmptyState.vue';const projects=ref<any[]>([]),loading=ref(true);onMounted(async()=>{const d=await api<any>('/api/dashboard');projects.value=d.projects;loading.value=false})</script>
<template><div class="page-heading"><div><span class="eyebrow">自动化部署</span><h1>工作流</h1><p>按项目查看、创建和维护可视化部署流程。</p></div></div><div v-if="loading" class="project-grid"><div v-for="n in 4" :key="n" class="card skeleton stat-card"></div></div><div v-else class="project-grid"><router-link v-for="p in projects" :key="p.id" :to="`/projects/${p.id}/workflows`" class="card project-card"><div class="card-icon"><Workflow v-if="p.workflow_count"/><FolderKanban v-else/></div><div class="grow"><h3>{{p.name}}</h3><p>{{p.workflow_count}} 条工作流 · {{p.release_count}} 个发布版本</p><div class="mini-stats"><span>{{p.latest_version||'暂无发布'}}</span></div></div><ArrowUpRight class="arrow"/></router-link><EmptyState v-if="!projects.length" title="还没有项目" text="创建项目后即可配置部署工作流。"><router-link class="btn" to="/projects">创建项目</router-link></EmptyState></div></template>
